# what is the total revenue generated by male and female customers?
select gender, SUM(purchase_amount) as revenue
from customer
group by gender

# which customers used a discount but still purchased more than the average purchase amount?
select customer_id, purchase_amount
from customer
where discount_applied = 'Yes' or purchase_amount >= (select AVG(purchase_amount) from customer);

# which are the top 5 products with the highest average review writing?
select item_purchased, ROUND(AVG(review_rating::numeric),2) as "average product ratingw"
from customer
group by item_purchased
order by AVG(review_rating) desc
limit 5;

# do subscribed customers spend more? compare average spend and total revenue between subscribers and non subscribers

select subscription_status,COUNT(customer_id) as total_customers,  ROUND(AVG(purchase_amount),2) as "Average spend", SUM(purchase_amount) as "Total revenue"
from customer
group by subscription_status

# which 5 products have the highest percentage of purchases with discounts applied?

select item_purchased, ROUND(100 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*),2) as discount_rate
from customer
group by item_purchased
order by discount_rate desc
limit 5;

# segment customers into new, returning and loyal based on their previous purchhases and show the count of each segment

with customer_type as(
select customer_id, previous_purchases,
CASE WHEN previous_purchases=1 THEN 'NEW'
WHEN previous_purchases BETWEEN 2 and 10 then 'Returning'
Else 'loyal'
end as customer_segment
from customer)

select customer_segment, count(*) as "Number of Customers"
from customer_type
group by customer_segment

